import{_ as e,o,c as t,a0 as l}from"./chunks/framework.IrjkP_YN.js";const u=JSON.parse('{"title":"商标法明年要改版，所以我把法条存进了数据库","description":"","frontmatter":{},"headers":[],"relativePath":"posts/law-as-data.md","filePath":"posts/law-as-data.md","lastUpdated":null}'),r={name:"posts/law-as-data.md"};function p(s,a,i,d,n,c){return o(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="商标法明年要改版-所以我把法条存进了数据库" tabindex="-1">商标法明年要改版，所以我把法条存进了数据库 <a class="header-anchor" href="#商标法明年要改版-所以我把法条存进了数据库" aria-label="Permalink to &quot;商标法明年要改版，所以我把法条存进了数据库&quot;">​</a></h1><p>2026-09</p><h2 id="本来打算-if-else-一把梭" tabindex="-1">本来打算 if else 一把梭 <a class="header-anchor" href="#本来打算-if-else-一把梭" aria-label="Permalink to &quot;本来打算 if else 一把梭&quot;">​</a></h2><p>我那个项目原来是给人取名的，表单填一下，后端去 Milvus 检索诗词，出五个名字带出处。跑通了，也上线了。</p><p>九月中旬我想加个品牌取名的方向，顺手做一层商标风险提示。当时想法特别朴素：把《商标法》第十条、第十一条抄进代码，写一堆 if，完事。</p><p>抄到一半我去搜了下原文，然后人傻了。</p><p>商标法 2026 年 6 月 26 日刚修订通过，2027 年 1 月 1 日施行。禁止性标志那一条，从第十条整个搬到了第十五条。</p><p>我代码里要是写死「第十条第一款第（一）项」，四个多月以后它就是一个不存在的编号了。</p><h2 id="我第一反应是推倒重来" tabindex="-1">我第一反应是推倒重来 <a class="header-anchor" href="#我第一反应是推倒重来" aria-label="Permalink to &quot;我第一反应是推倒重来&quot;">​</a></h2><p>真的。我当时的原话是「我感觉可改性好低，还是说要重新开始一个」。</p><p>后来发现不用。要改的只是「法条放在哪」这一件事，检索、生成、接口那些都不用动。所以我把法条从代码里搬进了数据库，两张表：</p><ul><li><code>law_version</code>：哪部法、哪个版本、什么时候生效、什么时候失效</li><li><code>law_clause</code>：条款号、条款原文、风险等级，外键指向版本</li></ul><p>现在代码里一句法条都没有。要用的时候按今天的日期查「当前生效的那一版」，再把这一版底下的条款全捞出来拼成提示词。库里实测 1 行版本 + 15 行条款。</p><p>生效日期我放在版本表上，不是条款表上。这个我一开始想错了，我当时的理由是「放哪都行，反正以后能扩展」。这话听着挺对，其实是废话——两张表都能扩展。真正的理由是：生效日期是「版本」的属性，不是「条款」的属性，放条款表上同一个日期要重复十五遍。</p><h2 id="一个坑-条款号不能单独唯一" tabindex="-1">一个坑：条款号不能单独唯一 <a class="header-anchor" href="#一个坑-条款号不能单独唯一" aria-label="Permalink to &quot;一个坑：条款号不能单独唯一&quot;">​</a></h2><p>我本来给 <code>clause_number</code> 加了个唯一约束，觉得一个条款号当然只对应一条。</p><p>然后想到新旧法会撞号。2019 版的第十五条讲的是代理人抢注被代理人的商标，2026 版的第十五条讲的是禁止性标志。完全不同的两件事，同一个编号。</p><p>只按条款号查，将来会<strong>静默取错</strong>——不报错，就是把另一个版本的内容给你。所以唯一约束改成了 <code>(version_id, clause_number)</code>。</p><p>这个我是先写完约束、后来才想到的，属于运气好。要是 2027 年才发现，那就是线上事故。</p><h2 id="_2027-年-1-月-1-日那天我要干什么" tabindex="-1">2027 年 1 月 1 日那天我要干什么 <a class="header-anchor" href="#_2027-年-1-月-1-日那天我要干什么" aria-label="Permalink to &quot;2027 年 1 月 1 日那天我要干什么&quot;">​</a></h2><p>想明白这个的时候我挺爽的。</p><p>那天我只用做三件事：<code>law_version</code> 加一行（2026 修订版，生效日期 2027-01-01，同时把 2019 版的失效日期填上）、<code>law_clause</code> 加一批新条款、禁用字样的映射表加一个新版本的块。</p><p><strong>现有数据一个字都不用动。</strong></p><p>因为代码是按今天的日期查生效版本的，那天一到它自己就换新版了。模型甚至不知道法条改了——它看到的永远是「一堆条款，每条前面带个编号」，而那个编号是数据库主键，不是条款号字符串。</p><p>顺便说下失效日期那个查询，我写的是 <code>expiry_date &gt; 今天</code>，不是 <code>&gt;=</code>。因为「失效日期」的意思是从这天起不再有效，所以 2027-01-01 当天 2019 版就不该被选中了。这样配下来任何一天都恰好命中一版，不重叠也不断档。我还加了个守卫，查出 0 行或者 2 行都直接报错，不默默取第一个。</p><h2 id="有一个地方我到现在也不敢说一定对" tabindex="-1">有一个地方我到现在也不敢说一定对 <a class="header-anchor" href="#有一个地方我到现在也不敢说一定对" aria-label="Permalink to &quot;有一个地方我到现在也不敢说一定对&quot;">​</a></h2><p>第十条第二款（地名那条）到底算「禁止使用」还是「不予注册」，我查了半天没查出准话。</p><p>商标局的指引写的是「不得作为商标注册和使用」，但好几篇实务文章把它放在「不予注册」的依据底下，理由是地名缺乏显著性、容易让人误认产地。有律所的文章干脆把两种观点都列出来了。</p><p>我最后填的「禁止使用」。</p><p>我不是学法的，这一格我到现在也不敢说一定对。但我觉得<strong>知道这里有争议</strong>比填对了更重要——所以这一条的输出措辞我放得最软，写的是「存在被驳回风险」，不是「违反第十条」。</p><h2 id="_15-条法条是一个字一个字抄的" tabindex="-1">15 条法条是一个字一个字抄的 <a class="header-anchor" href="#_15-条法条是一个字一个字抄的" aria-label="Permalink to &quot;15 条法条是一个字一个字抄的&quot;">​</a></h2><p>全部从国家知识产权局的官方页面抄的，没让模型生成过一条。</p><p>为什么这么小心，下一篇讲。简短版：我被模型编的出处坑过一次，而且那两句诗是真的。</p><p>顺带记一下 15 条是怎么构成的，因为我这里也错过一次：第十条第一款引导语 1 条 + 八个项 + 第十条第二款 1 条 + 第十一条第一款引导语 1 条 + 三个项 + 第十一条第二款 1 条。</p><p><strong>引导语必须单独占一行。</strong> 不然第（一）项的原文就成了「仅有本商品的通用名称、图形、型号的」这种半句话，模型看不到「下列标志不得作为商标注册」这个前提，它根本不知道这些项在说什么。</p><p>我一开始算出来是 13 条，因为漏了两条引导语。后来是对着数据库一行行数出来的。</p><h2 id="还没做的" tabindex="-1">还没做的 <a class="header-anchor" href="#还没做的" aria-label="Permalink to &quot;还没做的&quot;">​</a></h2><ul><li>2026 修订版的条款一条都还没录。还没施行，而且我想等临近了再录，免得录错了没人发现</li><li>导入脚本重跑会撞唯一约束（版本已存在就进 else 分支，然后又插 15 条重复条款）。它是响亮失败不是静默失败，所以不危险，我打算 2027 年加新版本的时候一起修</li><li>第十条第一款第（四）项那个「官方标志、检验印记」，我名录里录了 10 条，其中 9 条是按定义推的，只有「中国强制性产品认证（CCC）」有权威依据。这 9 条我知道不实，措辞上也没敢写「违反第（四）项」</li></ul><hr><p>代码在 <a href="https://github.com/wangxihong-dev/ai-name-assistant" target="_blank" rel="noreferrer">GitHub</a>，<code>models/law_version.py</code> 和 <code>law_clause.py</code> 就是那两张表。</p>',40)])])}const _=e(r,[["render",p]]);export{u as __pageData,_ as default};
